import { useMemo, useState } from 'react'
import isEmpty from 'lodash/isEmpty'
import { Row } from '../../../commonStyle/index.style'
import { CustomText } from '../../../components'
import PolicyAmountDistribution from '../../../components/AmountDistribution'
import PolicyInfo from '../../../components/PolicyCancelledRejectionInfo'
import ImageGuideModal from '../../../components/PolicyCustAgentForm/components/ImageGuideModal'
import QuickViewPackageCard from '../../../components/QuickViewPackageCard'
import SingleImgContainer from '../../../components/SingleImgContainer'
import StepsHeader from '../../../components/StepsHeader'
import TitleError from '../../../components/TitleError'
import ZoomImg from '../../../components/zoomImg'
import { AgentColorPallette } from '../../../configs/colorPallete'
import { formatMoney } from '../../../helpers/utility'
import { LANG_STRINGS } from '../../../lang'
import { formatDate } from '../../../helpers/formatDate'
import { PROPERTY_LANG } from '../../Private/Property/lang'
import { BUILDING_IMGS } from '../PropertyDetailForm/constants'
import { PropertySummaryCard, PropertySummaryStyle } from './index.style'
import {
  genderMap,
  maritalStatusMap,
  propertyOwnershipMap,
  hardcopySentToMap,
} from './helpers'

function PropertyPolicySummary(props) {
  const {
    step,
    totalSteps,
    draftResponseData = {},
    policyDetail = {},
    isConvertToPaylater,
    setIsConvertToPaylater,
    onSubmit,
  } = props

  const packageDetail = useMemo(
    () => policyDetail?.package_data || {},
    [policyDetail]
  )

  const [modalContent, setModalContent] = useState({})

  const handleSubmitFormConfirmation = () => {
    // handle the form submission
    if (onSubmit) {
      onSubmit()
    }
  }

  const getCardTitle = (title, top, weight = 700) => {
    return (
      <CustomText
        size="16px"
        weight={weight}
        top={top}
        color={AgentColorPallette.mustard}
      >
        {title}
      </CustomText>
    )
  }

  const getTitleSubtitle = (title, subTitle) => {
    if (!subTitle) return null
    return (
      <div className="card-title-subtitle">
        <CustomText size="11px" color={AgentColorPallette.fontSemiGrey}>
          {title}
        </CustomText>
        <CustomText
          className="break-word-newline"
          size="13px"
          color={AgentColorPallette.black}
          weight={700}
        >
          {subTitle}
        </CustomText>
      </div>
    )
  }

  const renderPolicyCard = () => {
    return (
      <QuickViewPackageCard
        packageLogo={packageDetail?.provider?.logo_url}
        providerName={packageDetail?.provider?.name}
        packageName={packageDetail?.package?.name}
        amount={formatMoney(
          packageDetail?.premium_breakup?.base_premium?.premium,
          0
        )}
        periodText={LANG_STRINGS.mvPeriod}
      />
    )
  }

  const renderCustomerData = () => {
    const customerData = policyDetail?.customer_data
    const isIndividualCustomer =
      policyDetail?.customer_data?.type === 'individual'
    const isCorporateCustomer =
      policyDetail?.customer_data?.type === 'corporate'
    return (
      <PropertySummaryCard>
        {getCardTitle(PROPERTY_LANG.insuredInformation)}
        {isIndividualCustomer && (
          <>
            {getTitleSubtitle(
              LANG_STRINGS.ktpKitasPhoto,
              <ZoomImg
                src={customerData?.ktp_url}
                imgContainer={
                  <SingleImgContainer
                    minWidth="0px"
                    imgUrl={customerData?.ktp_url}
                  />
                }
              />
            )}
            {getTitleSubtitle(
              LANG_STRINGS.ktpKitasNumber,
              customerData?.ktp_no
            )}
            {getTitleSubtitle(LANG_STRINGS.ktpKitasName, customerData?.name)}
            {getTitleSubtitle(
              LANG_STRINGS.gender,
              genderMap[customerData?.gender]
            )}
            {getTitleSubtitle(
              LANG_STRINGS.maritalStatus,
              maritalStatusMap[customerData?.marital_status]
            )}
            {getTitleSubtitle(
              LANG_STRINGS.phoneNumber,
              customerData?.mobile_no
            )}
            {getTitleSubtitle(LANG_STRINGS.email, customerData?.email)}
            {!isEmpty(customerData?.customer_address) && (
              <>
                {getTitleSubtitle(
                  LANG_STRINGS.province,
                  customerData?.customer_address?.province_name
                )}
                {getTitleSubtitle(
                  LANG_STRINGS.city,
                  customerData?.customer_address?.city_name
                )}
                {getTitleSubtitle(
                  LANG_STRINGS.postalCode,
                  customerData?.customer_address?.postal_code
                )}
                {getTitleSubtitle(
                  LANG_STRINGS.addressDetail,
                  customerData?.customer_address?.address
                )}
              </>
            )}
          </>
        )}
        {isCorporateCustomer && (
          <>
            {getTitleSubtitle(
              PROPERTY_LANG.corporateNpwpPhoto,
              <ZoomImg
                src={customerData?.corporate_data?.npwp_url}
                imgContainer={
                  <SingleImgContainer
                    minWidth="0px"
                    imgUrl={customerData?.corporate_data?.npwp_url}
                  />
                }
              />
            )}
            {getTitleSubtitle(
              PROPERTY_LANG.corporateNpwpNumber,
              customerData?.corporate_data?.npwp_no
            )}
            {getTitleSubtitle(
              PROPERTY_LANG.corporateName,
              customerData?.corporate_data?.name
            )}
            {getTitleSubtitle(
              PROPERTY_LANG.corporateType,
              customerData?.corporate_data?.corporate_type_data?.mitra_name
            )}
            {getTitleSubtitle(
              PROPERTY_LANG.economicActivity,
              customerData?.corporate_data?.economic_activity_data?.mitra_name
            )}
            {getTitleSubtitle(
              PROPERTY_LANG.foundingDate,
              formatDate(
                customerData?.corporate_data?.founding_date,
                'DD/MM/YYYY'
              )
            )}
            {getTitleSubtitle(
              PROPERTY_LANG.countryOfOrigin,
              customerData?.corporate_data?.country_of_origin
            )}
            {getTitleSubtitle(
              PROPERTY_LANG.picName,
              customerData?.corporate_data?.pic_name
            )}
            {getTitleSubtitle(
              PROPERTY_LANG.picPhoneNumber,
              customerData?.corporate_data?.pic_mobile_no
            )}
            {getTitleSubtitle(
              PROPERTY_LANG.picEmail,
              customerData?.corporate_data?.pic_email
            )}
            {!isEmpty(customerData?.customer_address) && (
              <>
                {getTitleSubtitle(
                  LANG_STRINGS.province,
                  customerData?.customer_address?.province_name
                )}
                {getTitleSubtitle(
                  LANG_STRINGS.city,
                  customerData?.customer_address?.city_name
                )}
                {getTitleSubtitle(
                  LANG_STRINGS.postalCode,
                  customerData?.customer_address?.postal_code
                )}
                {getTitleSubtitle(
                  LANG_STRINGS.addressCorporate,
                  customerData?.customer_address?.address
                )}
              </>
            )}
          </>
        )}
      </PropertySummaryCard>
    )
  }

  const renderBuildingInformation = () => {
    const propertyBreakup =
      packageDetail?.premium_breakup?.property_sum_insured_breakup
    return (
      <PropertySummaryCard>
        {getCardTitle(PROPERTY_LANG.buildingInformation)}
        {getTitleSubtitle(PROPERTY_LANG.province, policyDetail?.province_name)}
        {getTitleSubtitle(PROPERTY_LANG.city, policyDetail?.city_name)}
        {getTitleSubtitle(PROPERTY_LANG.postalCode, policyDetail?.postal_code)}
        {getTitleSubtitle(
          PROPERTY_LANG.insuredObjectLocation,
          policyDetail?.location
        )}
        {getTitleSubtitle(
          PROPERTY_LANG.buildingCategory,
          policyDetail?.property_data?.occupation_data?.occupation_remarks
        )}
        {getTitleSubtitle(
          PROPERTY_LANG.buildingUse,
          policyDetail?.property_data?.occupation_data?.occupation_remarks
        )}
        {getTitleSubtitle(
          PROPERTY_LANG.noOfFloor,
          policyDetail?.property_data?.no_of_floor
        )}
        {policyDetail?.questionnaire?.map((q) =>
          getTitleSubtitle(q.question, q.value ? 'Iya' : 'Tidak')
        )}
        {getTitleSubtitle(
          PROPERTY_LANG.propertyOwnership,
          propertyOwnershipMap[policyDetail?.customer_data?.type]
        )}
        {getTitleSubtitle(
          PROPERTY_LANG.ownerName,
          packageDetail?.customer_data?.name
        )}
        {getTitleSubtitle(
          PROPERTY_LANG.totalBuildingValue,
          formatMoney(propertyBreakup?.building_value, 0)
        )}
        {getTitleSubtitle(
          PROPERTY_LANG.totalValueOfBuildingContent,
          formatMoney(propertyBreakup?.building_content_value, 0)
        )}
        {getTitleSubtitle(
          PROPERTY_LANG.machineValue,
          formatMoney(propertyBreakup?.machine_value, 0)
        )}
        {getTitleSubtitle(
          PROPERTY_LANG.equipmentValue,
          formatMoney(propertyBreakup?.equipment_value, 0)
        )}
        {getTitleSubtitle(
          PROPERTY_LANG.stockValue,
          formatMoney(propertyBreakup?.stock_value, 0)
        )}
        {getTitleSubtitle(
          PROPERTY_LANG.totalSumInsured,
          formatMoney(packageDetail?.total_sum_insured, 0)
        )}
        {getTitleSubtitle(
          LANG_STRINGS.policyStartDate,
          formatDate(policyDetail?.start_date, 'DD/MM/YYYY [12:00 Siang]')
        )}
        {getTitleSubtitle(
          LANG_STRINGS.policyEndDate,
          formatDate(policyDetail?.end_date, 'DD/MM/YYYY [12:00 Siang]')
        )}
      </PropertySummaryCard>
    )
  }

  const renderBuildingImage = () => {
    return (
      <PropertySummaryCard>
        {getCardTitle(PROPERTY_LANG.buildingPhotos)}
        {BUILDING_IMGS.map((imgTypes) => {
          const imgByType = policyDetail[imgTypes.type] || {}
          return (
            <div key={imgTypes.type}>
              <TitleError title={imgTypes.title} />
              <Row align="center" className="summary-images">
                {Object.values(imgByType)?.map((img, i) => (
                  <ZoomImg key={i} src={img} imgClassName="img-container" />
                ))}
              </Row>
            </div>
          )
        })}
      </PropertySummaryCard>
    )
  }

  const renderPrintPolicy = () => {
    if (!packageDetail?.hard_copy_enabled) {
      // Check if provider/package allows hardcopy
      return null
    }
    return (
      <PropertySummaryCard>
        {getCardTitle(LANG_STRINGS.printPolicy)}
        {policyDetail?.hard_copy_required ? (
          <>
            {getTitleSubtitle(
              LANG_STRINGS.shippingOption,
              hardcopySentToMap[policyDetail?.hard_copy_sent_to]
            )}
            {getTitleSubtitle(
              PROPERTY_LANG.shippingAddress,
              policyDetail?.hard_copy_address?.address
            )}
            {getTitleSubtitle(
              PROPERTY_LANG.province,
              policyDetail?.hard_copy_address?.province_name
            )}
            {getTitleSubtitle(
              PROPERTY_LANG.city,
              policyDetail?.hard_copy_address?.city_name
            )}
            {getTitleSubtitle(
              PROPERTY_LANG.postalCode,
              policyDetail?.hard_copy_address?.postal_code
            )}
            {policyDetail?.hard_copy_recipient &&
              getTitleSubtitle(
                LANG_STRINGS.recipientName,
                policyDetail?.hard_copy_recipient
              )}
            {policyDetail?.hard_copy_recipient_mobile &&
              getTitleSubtitle(
                LANG_STRINGS.phoneNumber,
                policyDetail?.hard_copy_recipient_mobile
              )}
          </>
        ) : (
          <CustomText
            top="10px"
            size="13px"
            color={AgentColorPallette.fontDarkerGrey}
          >
            {LANG_STRINGS.thisOptionIsNotSelected}
          </CustomText>
        )}
      </PropertySummaryCard>
    )
  }

  const isApplicationCancelled = useMemo(() => {
    const status = draftResponseData?.policy_status
    return status === 'CANCELLED' || status === 'REJECTED'
  }, [draftResponseData])

  return (
    <PropertySummaryStyle>
      <PolicyInfo
        remarks={draftResponseData?.insurance_details?.remark_details || {}}
        status={draftResponseData?.policy_status || ''}
        marginTop="18px"
      />
      <StepsHeader
        current={step}
        totalSteps={totalSteps}
        leftText={PROPERTY_LANG.orderDetails}
        className={`${isApplicationCancelled ? 'mt-0' : ''}`}
      />
      <div className="property-summary">
        <CustomText
          color={AgentColorPallette.darkerGold}
          bottom="20px"
          size="16px"
          lineHeight={1.5}
        >
          {PROPERTY_LANG.pleaseCheckAllDataBeforePay}
        </CustomText>
        {renderPolicyCard()}
        {renderCustomerData()}
        {renderBuildingInformation()}
        {renderBuildingImage()}
        {renderPrintPolicy()}
      </div>
      <PolicyAmountDistribution
        pkgDetail={packageDetail}
        discount={policyDetail.discount}
        hideDiscount={!policyDetail.discount}
        showAgentCommission={false}
        onChoosePayment={handleSubmitFormConfirmation}
        btnText={LANG_STRINGS.next}
        className="property-premium-box"
        position="relative"
        hidePaymentBtn={isApplicationCancelled}
        subTitle={PROPERTY_LANG.startDateMinDateDisclaimer}
        isShowConvertToPaylater={true}
        isConvertToPaylaterChecked={isConvertToPaylater}
        onConvertToPaylaterClick={() =>
          setIsConvertToPaylater(!isConvertToPaylater)
        }
      />
      {modalContent.showImgModal && (
        <ImageGuideModal
          showImgModal={modalContent.showImgModal}
          title={modalContent.modalTitle}
          onClose={() => setModalContent({})}
          modalImgContainer={modalContent.imgContainer}
        />
      )}
    </PropertySummaryStyle>
  )
}

export default PropertyPolicySummary
